import { definePrimitive, dispatch, type ChangeDetails, type ChangeOptions } from "@ui-sdk/core"

type ListSelectReason = "item-press" | "imperative"

type ListEntry = { value: string; label: string }

type ListOptions = {
  /** The rows as agents see them, collected from the rendered items. */
  entries?: readonly ListEntry[]
  /** Runs before a row is chosen, by a person or an agent; `details.cancel()` stops it. */
  onSelect?: (id: string, details: ChangeDetails<ListSelectReason>) => void
  /** What choosing a row does once `onSelect` allowed it, when no event will do it natively. */
  activate?: (id: string) => boolean
}

function reasonOf(options: unknown): { reason: ListSelectReason; event?: Event } {
  if (typeof options !== "object" || options === null) return { reason: "imperative" }
  const { reason = "imperative", event } = options as ChangeOptions<ListSelectReason>
  return { reason, event: event instanceof Event ? event : undefined }
}

const list = definePrimitive({
  name: "list",
  options: { entries: "value", onSelect: "callback", activate: "value" },
  state: (options: ListOptions) => ({ count: options.entries?.length ?? 0 }),
  sync: (options) => ({ count: options.entries?.length ?? 0 }),
  api: (context) => {
    const entries = () => context.options().entries ?? []
    return {
      // The agent bridge passes arguments unchecked.
      select(id: unknown, options?: ChangeOptions<ListSelectReason>) {
        if (!entries().some((entry) => entry.value === id)) {
          const ids = entries().map((entry) => entry.value)
          throw new RangeError(`No row "${String(id)}". Rows: ${ids.join(", ")}.`)
        }
        const details = reasonOf(options)
        if (dispatch(context, "onSelect", id as string, details)) return false
        // A person's click already follows the link or presses the button; only other callers need it done.
        if (details.event) return true
        return context.options().activate?.(id as string) ?? true
      },
      entries,
    }
  },
  slots: (slot) => ({
    root: slot({ role: "group", attrs: (state) => ({ "data-count": String(state.count) }) }),
  }),
  agent: { actions: ["select"], items: (api) => api.entries() },
})

export { list }
export type { ListEntry, ListOptions, ListSelectReason }

"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import {
  createListboxController,
  Listbox,
  ListboxGroup,
  ListboxGroupLabel,
  type ListboxValueChangeReason,
} from "@ui-sdk/react/listbox"
import { usePart, usePrimitive, type PartProps } from "@ui-sdk/react/primitive"
import {
  createContext,
  memo,
  use,
  useCallback,
  useId,
  useMemo,
  useRef,
  useState,
  type FocusEvent,
  type KeyboardEvent,
  type ReactNode,
} from "react"

import { list, type ListEntry, type ListOptions } from "@/components/ui/list-primitive"
import { RowNavigationProvider, useRowNavigation } from "@/components/ui/row-navigation"
import { GapFindStubs, useVirtualRows, type Virtualize } from "@/components/ui/virtual-rows"
import { cn } from "@/lib/utils"

type ListVariant = "row" | "card"
type ItemHandle = { label: string; activate: () => boolean }

type ListContextValue = {
  variant: ListVariant
  selectable: boolean
  register: (id: string, handle: ItemHandle) => () => void
  select: (id: string, event: Event) => boolean
  /** Rows that Space or `x` check, for bulk actions; undefined when the list has none. */
  checked?: { has: (id: string) => boolean; toggle: (id: string) => void }
}

/** Where a data row sits among all rows, while the list is virtualized. */
type ListItemPosition = { index: number; setsize: number; measure?: (node: HTMLElement | null) => void }

const ListContext = createContext<ListContextValue | null>(null)
const PositionContext = createContext<ListItemPosition | null>(null)

function useListContext() {
  return use(ListContext)
}

function useListItemPosition() {
  return use(PositionContext)
}

const containerClassNames = {
  row: "flex flex-col",
  card: "grid grid-cols-[repeat(auto-fill,minmax(min(100%,18rem),1fr))] gap-items",
} satisfies Record<ListVariant, string>

type ListProps<Item = unknown> = Omit<PartProps<"div">, "children" | "onSelect" | "defaultValue"> & {
  /** Names the list, for screen readers and agents. */
  "aria-label": string
  variant?: ListVariant
  /** With any of `value`, `defaultValue` or `onValueChange`, the rows are options of a UI SDK Listbox. */
  value?: string | null
  defaultValue?: string | null
  onValueChange?: (id: string | null, details: ChangeDetails<ListboxValueChangeReason>) => void
  onSelect?: ListOptions["onSelect"]
  /** Rows as data, rendered by `renderItem`: every row is reachable by keyboard and agents, rendered or not. */
  items?: readonly Item[]
  getItemId?: (item: Item) => string
  renderItem?: (item: Item, index: number) => ReactNode
  /** A row's text, for agents and for find in page while it isn't rendered. */
  itemText?: (item: Item) => string
  /** `"auto"` (default) renders only the rows in view past 200 data rows. Rows only; cards never virtualize. */
  virtualize?: Virtualize
  /** A row's estimated height in px before it is measured. */
  estimateSize?: number
  /** Rows checked for a bulk action: Space or `x` on a row toggles it, and each row shows a checkbox. */
  checkedIds?: readonly string[]
  onCheckedIdsChange?: (ids: string[]) => void
  children?: ReactNode
}

function rootAttributes(variant: ListVariant, selectable: boolean) {
  return { "data-slot": "list", "data-variant": variant, "data-selectable": selectable ? "" : undefined }
}

function defaultText(item: unknown) {
  if (typeof item === "string") return item
  if (typeof item === "object" && item !== null) {
    const record = item as Record<string, unknown>
    for (const key of ["title", "label", "name", "id"]) if (typeof record[key] === "string") return record[key]
  }
  return ""
}

function defaultId(item: unknown) {
  if (typeof item === "object" && item !== null && "id" in item) return String((item as { id: unknown }).id)
  return String(item)
}

const listboxKeys: Record<string, string> = { j: "ArrowDown", k: "ArrowUp" }

// The listbox moves with arrows; j and k are the same moves, and the page keys jump by a screen of options.
function listboxKeyDown(event: KeyboardEvent<HTMLElement>, setValue: (id: string) => void) {
  if (event.altKey || event.ctrlKey || event.metaKey || !(event.target instanceof HTMLElement)) return
  const option = event.target.closest<HTMLElement>('[role="option"]')
  if (!option) return
  const arrow = listboxKeys[event.key]
  if (arrow) {
    event.preventDefault()
    event.stopPropagation()
    option.dispatchEvent(new globalThis.KeyboardEvent("keydown", { key: arrow, bubbles: true, cancelable: true }))
    return
  }
  if (event.key !== "PageDown" && event.key !== "PageUp") return
  const options = [...event.currentTarget.querySelectorAll<HTMLElement>('[role="option"]')]
  const viewport = event.currentTarget.closest<HTMLElement>("[data-slot=list]")?.parentElement?.clientHeight ?? 0
  const page = Math.max(1, Math.floor(viewport / Math.max(1, option.offsetHeight)) - 1)
  const from = options.indexOf(option)
  const target = options[Math.min(options.length - 1, Math.max(0, from + (event.key === "PageDown" ? page : -page)))]
  const id = target?.dataset.itemId
  if (!target || id === undefined) return
  event.preventDefault()
  target.scrollIntoView({ block: "nearest" })
  target.focus()
  setValue(id)
}

type ListRowProps<Item> = {
  item: Item
  index: number
  setsize?: number
  measure?: ListItemPosition["measure"]
  renderItem: (item: Item, index: number) => ReactNode
}

// Memoized: scrolling re-renders the list for its new range, and rows already in view stay as they are.
const ListRow = memo(function ListRow<Item>({ item, index, setsize, measure, renderItem }: ListRowProps<Item>) {
  const position = useMemo(
    () => (setsize === undefined ? null : { index, setsize, measure }),
    [index, setsize, measure],
  )
  return <PositionContext value={position}>{renderItem(item, index)}</PositionContext>
}) as <Item>(props: ListRowProps<Item>) => ReactNode

function List<Item = unknown>({
  "aria-label": label,
  variant = "row",
  value,
  defaultValue,
  onValueChange,
  onSelect,
  items: data,
  getItemId = defaultId,
  renderItem,
  itemText = defaultText,
  virtualize = "auto",
  estimateSize,
  checkedIds,
  onCheckedIdsChange,
  className,
  children,
  onFocus,
  ...props
}: ListProps<Item>) {
  const selectable = value !== undefined || defaultValue !== undefined || onValueChange !== undefined
  const items = useRef(new Map<string, ItemHandle>())
  const [registered, setRegistered] = useState<ListEntry[]>([])
  const [listbox] = useState(() => createListboxController<string>())

  const ids = useMemo(() => data?.map(getItemId), [data, getItemId])
  const indexOf = useMemo(() => new Map(ids?.map((id, index) => [id, index])), [ids])
  const dataEntries = useMemo(
    () => data?.map((item, index) => ({ value: ids?.[index] ?? "", label: itemText(item) })),
    [data, ids, itemText],
  )

  const { anchor, ...virtual } = useVirtualRows({
    count: data?.length ?? 0,
    virtualize: renderItem && variant === "row" ? virtualize : false,
    estimateSize,
    getKey: (index) => ids?.[index] ?? String(index),
  })

  // Data rows name themselves; registering only keeps their handles, since re-rendering here re-registers them.
  const fromData = data !== undefined
  const refresh = useCallback(() => {
    if (fromData) return
    setRegistered([...items.current].map(([id, handle]) => ({ value: id, label: handle.label })))
  }, [fromData])

  const handle = usePrimitive(list, {
    entries: dataEntries ?? registered,
    onSelect,
    activate: (id) => {
      if (selectable) return listbox.setValue(id)
      const index = indexOf.get(id)
      if (!items.current.has(id) && index !== undefined) virtual.renderNow(index)
      return items.current.get(id)?.activate() ?? false
    },
  })

  const checkedSet = useMemo(() => new Set(checkedIds), [checkedIds])
  const checked = useMemo(
    () =>
      onCheckedIdsChange && checkedIds
        ? {
            has: (id: string) => checkedSet.has(id),
            toggle: (id: string) =>
              onCheckedIdsChange(
                checkedSet.has(id) ? checkedIds.filter((checkedId) => checkedId !== id) : [...checkedIds, id],
              ),
          }
        : undefined,
    [checkedIds, checkedSet, onCheckedIdsChange],
  )

  const navigation = useRowNavigation({
    ids,
    onToggle: checked ? (id) => checked.toggle(id) : undefined,
    reveal: (id) => {
      const index = indexOf.get(id)
      if (index !== undefined) virtual.scrollToIndex(index)
    },
  })

  const context = useMemo<ListContextValue>(
    () => ({
      variant,
      selectable,
      checked,
      register: (id, item) => {
        items.current.set(id, item)
        refresh()
        return () => {
          if (items.current.get(id) === item) items.current.delete(id)
          refresh()
        }
      },
      select: (id, event) => handle.api.select(id, { reason: "item-press", event }),
    }),
    [variant, selectable, checked, refresh, handle],
  )

  const textAt = useCallback(
    (index: number) => (data?.[index] === undefined ? "" : itemText(data[index])),
    [data, itemText],
  )

  let rows: ReactNode = children
  if (data && renderItem) {
    const GapTag = selectable ? "div" : "li"
    rows = virtual.segments.map((segment) => {
      if (segment.type === "gap") {
        return (
          <GapTag key={segment.key} aria-hidden="true" data-slot="list-gap" style={{ height: segment.size }}>
            <GapFindStubs
              from={segment.from}
              to={segment.to}
              text={textAt}
              offsetOf={virtual.offsetOf}
              onFound={virtual.scrollToIndex}
            />
          </GapTag>
        )
      }
      const item = data[segment.index]
      if (item === undefined) return null
      return (
        <ListRow
          key={segment.key}
          item={item}
          index={segment.index}
          setsize={virtual.enabled ? data.length : undefined}
          measure={virtual.measureElement}
          renderItem={renderItem}
        />
      )
    })
  }

  const container = selectable ? (
    // The root's `select` covers the listbox for agents; two entries with one name would make a ref ambiguous.
    <Listbox<string>
      ref={anchor}
      data-agent-hidden=""
      controller={listbox}
      value={value}
      defaultValue={defaultValue}
      onValueChange={onValueChange}
      onHighlight={(_value, details) => {
        if (virtual.enabled && details.index >= 0) virtual.scrollToIndex(details.index)
      }}
      onKeyDownCapture={(event) => listboxKeyDown(event, (id) => listbox.setValue(id))}
      aria-label={label}
      className={cn(containerClassNames[variant], "outline-none", virtual.enabled && "relative")}
    >
      {rows}
    </Listbox>
  ) : (
    <ul ref={anchor} className={cn(containerClassNames[variant], virtual.enabled && "relative")}>
      {rows}
    </ul>
  )

  return usePart(
    handle,
    "root",
    {},
    {
      ...props,
      ...rootAttributes(variant, selectable),
      "aria-label": label,
      onFocus: (event: FocusEvent<HTMLDivElement>) => {
        onFocus?.(event)
        if (!virtual.enabled || !(event.target instanceof Element)) return
        const index = Number(event.target.closest<HTMLElement>("[data-index]")?.dataset.index ?? Number.NaN)
        if (!Number.isNaN(index)) virtual.pin(index)
      },
      className: cn("flex min-w-0 flex-col", className),
      children: (
        <ListContext value={context}>
          {selectable ? container : <RowNavigationProvider handle={navigation}>{container}</RowNavigationProvider>}
        </ListContext>
      ),
    },
    "div",
  )
}

type ListGroupProps = {
  label: ReactNode
  /** Shown beside the label, like "Proposed 3". */
  count?: number
  className?: string
  children: ReactNode
}

const groupLabelClassName =
  "flex items-center gap-inline px-inset-item text-meta tracking-meta text-muted-foreground uppercase"

function ListGroup({ label, count, className, children }: ListGroupProps) {
  const context = useListContext()
  const labelId = useId()
  const variant = context?.variant ?? "row"
  const heading = (
    <>
      {label}
      {count !== undefined && (
        <>
          {" "}
          <span className="tabular-nums">{count}</span>
        </>
      )}
    </>
  )
  if (context?.selectable) {
    return (
      <ListboxGroup
        render={<div data-slot="list-group" />}
        className={cn("flex flex-col gap-inline not-first:pt-group", className)}
      >
        <ListboxGroupLabel className={groupLabelClassName}>{heading}</ListboxGroupLabel>
        <div className={containerClassNames[variant]}>{children}</div>
      </ListboxGroup>
    )
  }
  return (
    <li data-slot="list-group" className={cn("flex flex-col gap-inline not-first:pt-group", className)}>
      <div id={labelId} className={groupLabelClassName}>
        {heading}
      </div>
      <ul aria-labelledby={labelId} className={containerClassNames[variant]}>
        {children}
      </ul>
    </li>
  )
}

export { List, ListGroup, useListContext, useListItemPosition }
export type { ItemHandle, ListGroupProps, ListItemPosition, ListProps, ListVariant }

"use client"

import { Button } from "@ui-sdk/react/button"
import { ListboxItem } from "@ui-sdk/react/listbox"
import { renderElement, type PartProps } from "@ui-sdk/react/primitive"
import { createElement, useState, type ComponentProps, type ReactElement, type ReactNode } from "react"

import { Checkbox, CheckboxIndicator } from "@/components/ui/checkbox"
import {
  useListContext,
  useListItemPosition,
  type ListVariant,
  List,
  ListGroup,
  type ListGroupProps,
  type ListProps,
} from "@/components/ui/list"
import { NavigableRow } from "@/components/ui/row-navigation"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { useListItemRegistration, useTruncated } from "@/components/ui/use-list-item"
import type { Tone } from "@/lib/tone"
import { cn } from "@/lib/utils"

const rowClassNames = {
  row: "rounded-control hover:bg-accent/60 data-checked:bg-accent/60 data-selected:bg-accent data-selected:text-accent-foreground",
  card: "rounded-lg border bg-card/(--glass-opacity) text-card-foreground shadow-surface backdrop-surface hover:border-ring data-selected:border-ring data-selected:bg-accent data-selected:text-accent-foreground data-selected:ring-3 data-selected:ring-ring/25",
} satisfies Record<ListVariant, string>

const stretchedClassNames = {
  row: "after:rounded-control",
  card: "after:rounded-lg",
} satisfies Record<ListVariant, string>

const toneClassNames = {
  neutral: "bg-neutral-soft text-neutral-soft-foreground",
  info: "bg-info-soft text-info-soft-foreground",
  success: "bg-success-soft text-success-soft-foreground",
  warning: "bg-warning-soft text-warning-soft-foreground",
  destructive: "bg-destructive-soft text-destructive-soft-foreground",
  violet: "bg-violet-soft text-violet-soft-foreground",
} satisfies Record<Tone, string>

/** An icon on a tinted square, for a row's `leading`. */
function IconTile({ tone = "neutral", className, render, ...props }: PartProps<"span"> & { tone?: Tone }) {
  return renderElement(
    "span",
    {
      "aria-hidden": true,
      "data-slot": "icon-tile",
      className: cn(
        "flex size-8 shrink-0 items-center justify-center rounded-control [&_svg]:size-4",
        toneClassNames[tone],
        className,
      ),
      ...props,
    },
    render,
  )
}

function ListItemTitle({ className, render, ...props }: PartProps<"span">) {
  return renderElement(
    "span",
    {
      "data-slot": "list-item-title",
      className: cn("line-clamp-2 min-w-0 text-body font-medium break-words", className),
      ...props,
    },
    render,
  )
}

function ListItemMeta({ className, render, ...props }: PartProps<"div">) {
  return renderElement(
    "div",
    {
      "data-slot": "list-item-meta",
      className: cn("flex flex-wrap items-center gap-inline text-caption text-muted-foreground", className),
      ...props,
    },
    render,
  )
}

// Above the stretched link or button, so each action stays its own target. On a narrow row, the trailing
// content and the actions wrap onto their own line instead of squeezing the title.
function ListItemActions({ className, render, ...props }: PartProps<"div">) {
  return renderElement(
    "div",
    {
      "data-slot": "list-item-actions",
      className: cn("relative z-10 flex shrink-0 items-center gap-inline self-center", className),
      ...props,
    },
    render,
  )
}

type ListItemProps = {
  id: string
  title: string
  leading?: ReactNode
  subtitle?: ReactNode
  /** A StatusPill; on a narrow row it wraps below the title instead of squeezing it. */
  status?: ReactNode
  /** Inline chips. */
  meta?: ReactNode
  /** An avatar or a time, at the end. */
  trailing?: ReactNode
  /** Buttons or a menu. Rows of a selectable List are options, which can't hold controls, so it ignores them. */
  actions?: ReactNode
  selected?: boolean
  href?: string
  onSelect?: () => void
  /** Overrides the List's variant. */
  variant?: ListVariant
  /** The checkbox's name in a list with `checkedIds`; English by default. */
  checkLabel?: string
  className?: string
}

function ListItem({
  id,
  title,
  leading,
  subtitle,
  status,
  meta,
  trailing,
  actions,
  selected = false,
  href,
  onSelect,
  variant: variantProp,
  checkLabel,
  className,
}: ListItemProps) {
  const context = useListContext()
  const position = useListItemPosition()
  const variant = variantProp ?? context?.variant ?? "row"
  const option = context?.selectable ?? false
  const [titleNode, setTitleNode] = useState<HTMLElement | null>(null)
  const truncated = useTruncated(titleNode)
  const [primary, setPrimary] = useState<HTMLElement | null>(null)

  useListItemRegistration(context?.register, id, title, option, () => {
    if (href) {
      if (!primary) return false
      // Marks the click as already selected, so the link only follows itself.
      primary.setAttribute("data-selecting", "")
      primary.click()
      return true
    }
    if (!onSelect) return false
    onSelect()
    return true
  })

  const titleText = (
    <ListItemTitle ref={setTitleNode} title={option && truncated ? title : undefined}>
      {title}
    </ListItemTitle>
  )
  const pressable = !option && (href !== undefined || onSelect !== undefined)
  const primaryProps = {
    ref: setPrimary,
    "data-slot": "list-item-primary",
    "aria-current": selected ? (href ? ("page" as const) : ("true" as const)) : undefined,
    className: cn(
      "min-w-0 cursor-pointer text-start outline-none after:absolute after:inset-0 focus-visible:after:ring-2 focus-visible:after:ring-ring",
      stretchedClassNames[variant],
    ),
    onClick: (event: React.MouseEvent<HTMLElement>) => {
      const target = event.currentTarget
      if (target.dataset.selecting !== undefined) {
        delete target.dataset.selecting
        return
      }
      if (context && !context.select(id, event.nativeEvent)) {
        event.preventDefault()
        return
      }
      if (!href) onSelect?.()
    },
    children: titleText,
  }
  const element: ReactElement<Record<string, unknown>> = href
    ? createElement("a", { href, ...primaryProps })
    : // UI SDK's Button keeps its own data-slot over a prop; the rendered element's props win.
      createElement(Button, {
        ...primaryProps,
        render: (props: ComponentProps<"button">) => <button {...props} data-slot="list-item-primary" />,
      } as Record<string, unknown>)
  let heading: ReactNode = titleText
  if (pressable) {
    // Always mounted, so the trigger keeps its element (and focus) when the title starts or stops fitting.
    heading = (
      <Tooltip type="label" disabled={!truncated}>
        <NavigableRow id={id} render={<TooltipTrigger render={element} />} />
        <TooltipContent>{title}</TooltipContent>
      </Tooltip>
    )
  }
  const checked = option ? undefined : context?.checked
  // Space and x on the row toggle it, so the box stays out of the tab order instead of adding a stop per row.
  const checkbox = checked && (
    <span className="relative z-10 flex min-h-lh shrink-0 items-center">
      <Checkbox
        render={(props) => <button {...props} tabIndex={-1} />}
        aria-label={checkLabel ?? `Select ${title}`}
        checked={checked.has(id)}
        onCheckedChange={() => checked.toggle(id)}
      >
        <CheckboxIndicator />
      </Checkbox>
    </span>
  )

  const body = (
    <>
      <div className="flex min-w-0 grow basis-60 items-start gap-items">
        {checkbox}
        {leading && (
          <span
            data-slot="list-item-leading"
            className="flex min-h-lh shrink-0 items-center text-muted-foreground [&_svg]:size-4"
          >
            {leading}
          </span>
        )}
        <div className="flex min-w-0 flex-1 flex-col gap-inline">
          <div className="flex flex-wrap items-start gap-x-items gap-y-inline">
            <div className="flex min-w-0 grow basis-48">{heading}</div>
            {status && <div className="relative z-10 flex shrink-0 items-center">{status}</div>}
          </div>
          {subtitle && <div className="line-clamp-1 text-body-sm text-muted-foreground">{subtitle}</div>}
          {meta && <ListItemMeta className="relative z-10 w-fit">{meta}</ListItemMeta>}
        </div>
      </div>
      {trailing && (
        <div className="relative z-10 ms-auto flex shrink-0 items-center gap-inline self-center text-caption text-muted-foreground">
          {trailing}
        </div>
      )}
      {actions && !option && <ListItemActions>{actions}</ListItemActions>}
    </>
  )

  const rowClassName = cn(
    "group/list-item relative flex min-w-0 flex-wrap items-start gap-items px-inset-item py-inset-item transition-colors duration-micro ease-standard",
    rowClassNames[variant],
    className,
  )

  if (option) {
    return (
      <ListboxItem
        ref={position?.measure}
        render={<div data-slot="list-item" />}
        value={id}
        index={position?.index}
        data-index={position?.index}
        data-item-id={id}
        data-variant={variant}
        className={cn(rowClassName, "cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-ring")}
      >
        {body}
      </ListboxItem>
    )
  }
  return (
    <li
      ref={position?.measure}
      data-index={position?.index}
      aria-posinset={position ? position.index + 1 : undefined}
      aria-setsize={position?.setsize}
      data-slot="list-item"
      data-item-id={id}
      data-variant={variant}
      data-selected={selected ? "" : undefined}
      data-checked={checked?.has(id) ? "" : undefined}
      data-pressable={pressable ? "" : undefined}
      className={rowClassName}
    >
      {body}
    </li>
  )
}

